"""User operations with duplicated validation logic."""
import re


def create_user(name: str, email: str, age: int) -> dict:
    """Create a new user record."""
    if not re.match(r'^[^@]+@[^@]+\.[^@]+$', email):
        raise ValueError(f'Invalid email: {email}')
    if age < 0 or age > 150:
        raise ValueError(f'Invalid age: {age}')
    return {'name': name, 'email': email, 'age': age, 'active': True}


def update_user(user: dict, email: str = None, age: int = None) -> dict:
    """Update user fields."""
    if email is not None:
        if not re.match(r'^[^@]+@[^@]+\.[^@]+$', email):
            raise ValueError(f'Invalid email: {email}')
        user = {**user, 'email': email}
    if age is not None:
        if age < 0 or age > 150:
            raise ValueError(f'Invalid age: {age}')
        user = {**user, 'age': age}
    return user


def register_admin(email: str, age: int, permissions: list) -> dict:
    """Register an admin user."""
    if not re.match(r'^[^@]+@[^@]+\.[^@]+$', email):
        raise ValueError(f'Invalid email: {email}')
    if age < 0 or age > 150:
        raise ValueError(f'Invalid age: {age}')
    return {'email': email, 'age': age, 'permissions': permissions, 'is_admin': True}
